// state.js — explicit game state machine + hook registry. FROZEN after the
// ux-scaffold lands (see the module-ownership contract): feature streams register hooks via
// on(); they do NOT edit this file. main.js owns the single instance.
//
// States (see the module-ownership contract for the transition map):
//   AIM           aiming a shot (cue visible, input active)
//   SIMULATING    transient, synchronous: kernel simulate() in flight
//   PLAYBACK      sampler-driven replay of the simulated shot
//   SETTLED       transient: shot finished, outcome computed, awaiting
//                 adjudication (flow.js routes to WIN/BALL_IN_HAND/AIM)
//   BALL_IN_HAND  scratch recovery: player drags the cue ball
//   WIN           9-ball down; flow.js re-racks after the banner
//
// Hook contract (exact signatures — additive registrations only):
//   on('stateChange', (next: string, prev: string, info?: object) => void)
//   on('shotComplete', (record: ShotRecord, outcome: {nine, scratch,
//                       pocketed: number[]}) => void)
//   on('frame', (t: number /* playback clock, s */, dt: number) => void)
// on() returns an unsubscribe function. Handlers run synchronously in
// registration order; a handler may call to() (flow.js adjudicates SETTLED).

export const STATES = Object.freeze(
  ['AIM', 'SIMULATING', 'PLAYBACK', 'SETTLED', 'BALL_IN_HAND', 'WIN']);

// 'playerChanged' | 'foulCalled' | 'gameWon' are emitted by flow.js
// (STREAM-B deviation, applied at integration): payloads
//   playerChanged {player}   foulCalled {player, fouls, reason}
//   gameWon {player, pocketed}
export const EVENTS = Object.freeze(['stateChange', 'shotComplete', 'frame',
  'playerChanged', 'foulCalled', 'gameWon']);

export function createStateMachine(initial = 'AIM') {
  let state = initial;
  const listeners = new Map(EVENTS.map((e) => [e, []]));

  function on(event, fn) {
    const list = listeners.get(event);
    if (!list) throw new Error(`unknown hook event: ${event}`);
    list.push(fn);
    return () => {
      const i = list.indexOf(fn);
      if (i >= 0) list.splice(i, 1);
    };
  }

  function emit(event, ...args) {
    const list = listeners.get(event);
    if (!list) throw new Error(`unknown hook event: ${event}`);
    for (const fn of [...list]) fn(...args); // snapshot: handlers may (un)register
  }

  /** Transition to `next` and emit stateChange(next, prev, info). */
  function to(next, info) {
    if (!STATES.includes(next)) throw new Error(`unknown state: ${next}`);
    const prev = state;
    state = next;
    emit('stateChange', next, prev, info);
  }

  return {
    get state() { return state; },
    is: (...states) => states.includes(state),
    to, on, emit,
  };
}
